llm.raw_content:
{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C30"],
      "claim": "Didanosine, a purine nucleoside analogue, had a median absolute F of 0.19 under fed conditions, below the 20% threshold, demonstrating that purine nucleosides can exhibit low oral bioavailability when absorption or stability is limited.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C22"],
      "claim": "Acyclovir, a guanine nucleoside analogue, has a human oral bioavailability of about 20%, at the lower boundary of the threshold and consistent with poor systemic availability of unmodified guanine nucleosides.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Emtricitabine, a nucleoside analogue, has an absolute oral bioavailability of 93%, showing that some nucleosides are highly bioavailable when structurally stabilized; however, it is a pyrimidine nucleoside with modifications that reduce metabolic cleavage.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C33"],
      "claim": "Tofogliflozin, a C-glucoside, has absolute oral bioavailability of 97.5%, but its hydrolysis-resistant C-glycosidic bond limits transferability to the N-riboside query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Guanosine is a natural purine ribonucleoside. The most mechanistically relevant analogues are purine nucleosides: didanosine shows F below 20% under fed conditions and acyclovir is at ~20%, indicating poor systemic availability for unmodified purine nucleosides. High-F SGLT2 inhibitors are C-glucosides with stable C-C bonds, and emtricitabine is a stabilized pyrimidine nucleoside; both are less transferable to the metabolically labile N-riboside guanosine. Therefore F <20% is more likely.",
  "evidence_gaps": [
    "No direct human absolute oral bioavailability measurement for guanosine itself.",
    "Didanosine data are confounded by acid lability and fed/fasting effects.",
    "Acyclovir is acyclic rather than a true riboside, limiting direct structural transfer.",
    "SGLT2 inhibitors are C-glucosides, not N-ribosides, so their high bioavailability may not reflect guanosine's metabolic lability."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

